describe('Horizontal Scrolling Disabled on Main Layout', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x');
  });

  it('should not allow horizontal scrolling on main layout', () => {
    cy.get('body').should('have.css', 'overflow-x', 'hidden');
    cy.get('html').should('have.css', 'overflow-x', 'hidden');

    const initialScrollLeft = cy.window().then(win => win.scrollX);

    cy.get('body').trigger('wheel', {
      deltaX: 100,
      deltaY: 0,
      wheelDeltaX: 100,
      wheelDeltaY: 0
    });

    cy.window().then(win => {
      expect(win.scrollX).to.equal(0);
    });
  });

  it('should prevent horizontal scroll on touch swipe gesture', () => {
    cy.get('[data-testid="main-content"]').should('exist');

    cy.get('body').trigger('touchstart', {
      touches: [{ clientX: 100, clientY: 100 }]
    });

    cy.get('body').trigger('touchmove', {
      touches: [{ clientX: 50, clientY: 100 }],
      changedTouches: [{ clientX: 50, clientY: 100 }]
    });

    cy.window().then(win => {
      expect(win.scrollX).to.equal(0);
    });
  });

  it('should maintain vertical scrolling while blocking horizontal scroll', () => {
    cy.get('body').should('have.css', 'overflow-y', 'auto');

    cy.get('body').scrollTo(0, 100);

    cy.window().then(win => {
      expect(win.scrollY).to.be.greaterThan(0);
      expect(win.scrollX).to.equal(0);
    });
  });

  it('should not have any horizontally overflowing elements', () => {
    cy.window().then(win => {
      const bodyWidth = win.document.body.offsetWidth;
      const htmlWidth = win.document.documentElement.offsetWidth;

      expect(bodyWidth).to.equal(htmlWidth);
    });

    cy.get('*').each(($el) => {
      cy.wrap($el).then($element => {
        const elementWidth = $element[0].offsetWidth;
        const parentWidth = $element[0].parentElement.offsetWidth;

        expect(elementWidth).to.be.lte(parentWidth + 1);
      });
    });
  });

  it('should handle edge case with nested scrollable containers', () => {
    cy.get('[data-testid="nested-scroll-container"]').should('exist');

    cy.get('[data-testid="nested-scroll-container"]').should('have.css', 'overflow-x', 'hidden');

    cy.get('[data-testid="nested-scroll-container"]').trigger('wheel', {
      deltaX: 50,
      deltaY: 0
    });

    cy.get('[data-testid="nested-scroll-container"]').then($el => {
      expect($el[0].scrollLeft).to.equal(0);
    });
  });
});
